import React, { useDeferredValue, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { motion, AnimatePresence } from "framer-motion";
import { Settings, X, Lock, User, LogOut, Check, Volume2, VolumeX, Accessibility, Type, Search, MousePointer2, Wifi } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { isSoundEnabled, setSoundEnabled } from "@/lib/sound";
import { animationsDisabled, setAnimationsDisabled } from "@/lib/motion-preference";
import { customCursorEnabled, setCustomCursorEnabled } from "@/lib/cursor-preference";
import { FONT_PREVIEW_TEXT, applyFont, getStoredFont, isFontAssetLoaded, preloadFont } from "@/lib/themes";
import { FONTS, FONT_LIBRARIES } from "@/lib/font-catalog";
import { allowSpeculativeFetch, getDataSaverMode, networkState, NETWORK_EVENT, setDataSaverMode } from "@/lib/network-policy";

export default function SettingsModal({ open, onClose, isAdmin }) {
  const [currentCode, setCurrentCode] = useState("");
  const [newCode, setNewCode] = useState("");
  const [codeSaved, setCodeSaved] = useState(false);
  const [codeError, setCodeError] = useState(false);
  const [soundOn, setSoundOn] = useState(isSoundEnabled());
  const [animationsOff, setAnimationsOff] = useState(animationsDisabled());
  const [customCursorOn, setCustomCursorOn] = useState(customCursorEnabled());
  const [currentFont, setCurrentFont] = useState(getStoredFont());
  const [fontPreviewLoaded, setFontPreviewLoaded] = useState(() => ({ "gnu-free-mono": true, [getStoredFont()]: true }));
  const [fontAvailability, setFontAvailability] = useState({});
  const [fontSearch, setFontSearch] = useState("");
  const [fontSource, setFontSource] = useState("featured");
  const [fontLimit, setFontLimit] = useState(18);
  const [dataSaver, setDataSaver] = useState(getDataSaverMode);
  const [connection, setConnection] = useState(networkState);
  const deferredFontSearch = useDeferredValue(fontSearch);

  useEffect(() => {
    if (!open) return;
    const storedFont = getStoredFont();
    setCurrentFont(storedFont);
    setFontPreviewLoaded((loaded) => ({ ...loaded, "gnu-free-mono": true, [storedFont]: true }));
    setCustomCursorOn(customCursorEnabled());
    if (!document.fonts) return;
    let cancelled = false;
    const aliases = {
      "transgender-grotesk": "TransgenderGroteskUI",
      "atlas-mono": "AtlasMonoUI",
    };
    const localFonts = FONTS.filter((font) => font.localOnly);
    Promise.all(localFonts.map(async (font) => {
      const alias = aliases[font.key];
      try {
        const loaded = await document.fonts.load(`16px "${alias}"`, FONT_PREVIEW_TEXT);
        return [font.key, loaded.length > 0];
      } catch {
        return [font.key, false];
      }
    })).then((entries) => {
      if (!cancelled) setFontAvailability(Object.fromEntries(entries));
    });
    return () => { cancelled = true; };
  }, [open]);

  useEffect(() => {
    setFontLimit(18);
  }, [fontSearch, fontSource]);

  useEffect(() => {
    const sync = (event) => {
      setDataSaver(getDataSaverMode());
      setConnection(event?.detail || networkState());
    };
    sync();
    window.addEventListener(NETWORK_EVENT, sync);
    return () => window.removeEventListener(NETWORK_EVENT, sync);
  }, []);

  const filteredFonts = useMemo(() => {
    const query = deferredFontSearch.trim().toLowerCase();
    return FONTS.filter((font) => {
      const matchesSource = fontSource === "all"
        || (fontSource === "featured" && font.featured)
        || (fontSource === "by-womxn" && font.source === "Libre Fonts by Womxn");
      const matchesSearch = !query || `${font.name} ${font.detail} ${font.source}`.toLowerCase().includes(query);
      return matchesSource && matchesSearch;
    });
  }, [deferredFontSearch, fontSource]);

  const visibleFonts = filteredFonts.slice(0, fontLimit);

  const warmFontPreview = async (font) => {
    if (!allowSpeculativeFetch() || fontPreviewLoaded[font.key]) return;
    await preloadFont(font.key);
    setFontPreviewLoaded((loaded) => ({ ...loaded, [font.key]: true }));
  };

  const handleFontSelect = (key) => {
    localStorage.setItem("mabis-font-picker-version", "7");
    localStorage.setItem("mabis-font-updated-at", String(Date.now()));
    setCurrentFont(key);
    applyFont(key).finally(() => {
      setFontPreviewLoaded((loaded) => ({ ...loaded, [key]: true }));
    });
  };

  const handleSaveCode = () => {
    const existing = localStorage.getItem("mabis_admin_code") || "10260";
    if (currentCode !== existing) { setCodeError(true); return; }
    if (newCode.trim().length === 0) return;
    localStorage.setItem("mabis_admin_code", newCode.trim());
    setCodeSaved(true);
    setCurrentCode("");
    setNewCode("");
    setCodeError(false);
    setTimeout(() => setCodeSaved(false), 2000);
  };

  return createPortal(
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
          className="mobile-sheet-backdrop fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4"
          onClick={onClose}>
          <motion.div
            initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }}
            onClick={(e) => e.stopPropagation()}
            className="mobile-sheet-panel bg-white rounded-2xl shadow-2xl w-full max-w-xl max-h-[85vh] overflow-y-auto">
            <div className="mobile-sheet-header bg-[#951E3A] px-6 py-4 flex items-center justify-between sticky top-0 z-10">
              <div className="flex items-center gap-2.5">
                <Settings className="w-5 h-5 text-white" />
                <h2 className="font-display font-bold text-white text-xl">Settings</h2>
              </div>
              <button onClick={onClose} className="text-white/70 hover:text-white p-1 rounded-lg hover:bg-white/10">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="mobile-sheet-body p-6 space-y-6">
              {/* Security — admin/editor only */}
              {isAdmin && (
                <div>
                  <div className="flex items-center gap-2 mb-3">
                    <Lock className="w-4 h-4 text-[#951E3A]" />
                    <h3 className="font-display font-bold text-gray-800 text-sm uppercase tracking-wide">Unlock Code</h3>
                  </div>
                  <p className="text-xs text-gray-400 mb-3">Change the password used to unlock admin actions (meeting mode, etc.).</p>
                  <input type="password" value={currentCode} onChange={(e) => { setCurrentCode(e.target.value); setCodeError(false); }} placeholder="Current code..."
                    className={`w-full h-9 rounded-lg border-2 px-3 text-sm font-semibold tracking-widest outline-none mb-2 ${codeError ? "border-red-400 bg-red-50" : "border-gray-200 focus:border-[#951E3A]/40"}`} />
                  {codeError && <p className="text-xs text-red-500 font-semibold mb-2">Current code is incorrect.</p>}
                  <input type="text" value={newCode} onChange={(e) => setNewCode(e.target.value)} placeholder="Enter new code..."
                    className="w-full h-9 rounded-lg border border-gray-200 px-3 text-sm font-semibold tracking-widest outline-none focus:border-[#951E3A]/40 mb-2" />
                  <button onClick={handleSaveCode}
                    className="w-full h-10 rounded-lg bg-[#951E3A] text-white text-sm font-bold hover:bg-[#7a1830] transition-colors flex items-center justify-center">
                    {codeSaved ? <Check className="w-4 h-4" /> : "Save"}
                  </button>
                  {codeSaved && <p className="text-xs text-green-600 font-semibold mt-2">Code updated!</p>}
                </div>
              )}

              {/* Typography */}
              <div>
                <div className="flex items-center justify-between gap-3 mb-2">
                  <div className="flex items-center gap-2">
                    <Type className="w-4 h-4 text-[#951E3A]" />
                    <h3 className="font-display font-bold text-gray-800 text-sm uppercase tracking-wide">UI Font</h3>
                  </div>
                  <span className="text-[10px] text-gray-400 tabular-nums">{FONTS.length} choices</span>
                </div>
                <p className="text-xs text-gray-400 mb-3">
                  Choose the typeface used across the interface. UnifontEX is reserved for explicitly marked Japanese and Chinese text, while GNU FreeSerif handles Thai, so fallback fonts cannot replace ordinary Lilex or Iosevka UI lettering.
                </p>

                <div className="rounded-xl border border-gray-200 bg-gray-50/50 p-3 mb-3">
                  <p className="text-[9px] uppercase tracking-[0.2em] text-gray-400 mb-1.5">Current UI preview</p>
                  <p className="text-[20px] leading-snug text-gray-900 break-words" style={{ fontFamily: "var(--font-body)" }}>
                    {FONT_PREVIEW_TEXT}
                  </p>
                </div>

                <div className="relative mb-2.5">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400" />
                  <input
                    type="search"
                    value={fontSearch}
                    onChange={(event) => setFontSearch(event.target.value)}
                    placeholder="Search the font library..."
                    className="w-full h-9 rounded-lg border border-gray-200 bg-white pl-9 pr-3 text-xs outline-none focus:border-[#951E3A]/40"
                  />
                </div>

                <div className="flex flex-wrap gap-1.5 mb-3">
                  <button
                    type="button"
                    onClick={() => setFontSource("featured")}
                    className={`px-2.5 py-1.5 rounded-full border text-[10px] font-bold ${fontSource === "featured" ? "bg-[#951E3A] text-white border-[#951E3A]" : "border-gray-200 text-gray-500"}`}
                  >
                    Featured
                  </button>
                  <button
                    type="button"
                    onClick={() => setFontSource("by-womxn")}
                    className={`px-2.5 py-1.5 rounded-full border text-[10px] font-bold ${fontSource === "by-womxn" ? "bg-[#951E3A] text-white border-[#951E3A]" : "border-gray-200 text-gray-500"}`}
                  >
                    Libre Fonts by Womxn
                  </button>
                  <button
                    type="button"
                    onClick={() => setFontSource("all")}
                    className={`px-2.5 py-1.5 rounded-full border text-[10px] font-bold ${fontSource === "all" ? "bg-[#951E3A] text-white border-[#951E3A]" : "border-gray-200 text-gray-500"}`}
                  >
                    All
                  </button>
                </div>

                <div className="grid gap-2.5">
                  {visibleFonts.map((font) => {
                    const selected = currentFont === font.key;
                    const available = font.localOnly ? fontAvailability[font.key] : true;
                    const previewReady = font.localOnly
                      || font.key === "gnu-free-mono"
                      || selected
                      || fontPreviewLoaded[font.key]
                      || (font.stylesheet && isFontAssetLoaded(font));
                    return (
                      <button
                        key={font.key}
                        type="button"
                        onClick={() => handleFontSelect(font.key)}
                        onPointerEnter={() => warmFontPreview(font)}
                        onFocus={() => warmFontPreview(font)}
                        aria-pressed={selected}
                        className={`w-full text-left rounded-xl border-2 p-3.5 transition-colors ${selected ? "border-[#951E3A] bg-[#951E3A]/5" : "border-gray-200 hover:border-[#951E3A]/30"}`}
                      >
                        <div className="flex items-start justify-between gap-3 mb-2.5">
                          <div className="min-w-0">
                            <div className="flex flex-wrap items-center gap-1.5">
                              <span className="text-sm font-bold text-gray-800">{font.name}</span>
                              {font.key === "gnu-free-mono" && (
                                <span className="rounded-full bg-[#951E3A] px-2 py-0.5 text-[9px] font-bold uppercase tracking-wider text-white">Default</span>
                              )}
                              {selected && <Check className="h-3.5 w-3.5 text-[#951E3A]" />}
                            </div>
                            <p className="text-[10px] leading-4 text-gray-400 mt-0.5">{font.detail}</p>
                          </div>
                          <div className="shrink-0 flex items-center gap-1.5">
                            <span className={`h-1.5 w-1.5 rounded-full ${available ? "bg-green-500" : available === false ? "bg-amber-400" : "bg-gray-300"}`} />
                            <span className="text-[9px] uppercase tracking-wider text-gray-400">
                              {font.localOnly
                                ? (available ? "Installed" : available === false ? "Fallback" : "Checking")
                                : previewReady ? "Loaded" : "On demand"}
                            </span>
                          </div>
                        </div>
                        <div
                          className="rounded-lg border border-gray-200 bg-white px-3 py-3 text-[17px] leading-snug text-gray-900 break-words"
                          style={{ fontFamily: previewReady ? font.body : "var(--font-body)" }}
                        >
                          {FONT_PREVIEW_TEXT}
                        </div>
                        {!previewReady && (
                          <p className="mt-2 text-[10px] leading-4 text-gray-400">
                            Preview stays unloaded to save data. Select this font to download it.
                          </p>
                        )}
                        {font.localOnly && available === false && (
                          <p className="mt-2 text-[10px] leading-4 text-amber-600">
                            This commercial face needs a licensed local/webfont copy. Go is active until that file is available.
                          </p>
                        )}
                      </button>
                    );
                  })}
                </div>

                {visibleFonts.length === 0 && (
                  <div className="rounded-lg border border-dashed border-gray-200 px-3 py-5 text-center text-xs text-gray-400">
                    No fonts match this search.
                  </div>
                )}
                {filteredFonts.length > visibleFonts.length && (
                  <button
                    type="button"
                    onClick={() => setFontLimit((value) => value + 18)}
                    className="mt-2.5 w-full h-9 rounded-lg border border-gray-200 text-xs font-bold text-gray-600 hover:border-[#951E3A]/30"
                  >
                    Show more · {filteredFonts.length - visibleFonts.length} remaining
                  </button>
                )}

                <div className="mt-3 grid gap-1.5">
                  {FONT_LIBRARIES.map((library) => (
                    <div key={library.key} className="flex flex-col gap-1 border-t border-gray-100 pt-2 text-[10px] sm:flex-row sm:items-start sm:justify-between sm:gap-3">
                      {library.url ? (
                        <a href={library.url} target="_blank" rel="noreferrer" className="font-bold text-gray-600 underline underline-offset-2">
                          {library.name}
                        </a>
                      ) : (
                        <span className="font-bold text-gray-600">{library.name}</span>
                      )}
                      <span className="leading-4 text-gray-400 sm:max-w-[70%] sm:text-right">{library.detail}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Sound */}
              <div>
                <div className="flex items-center gap-2 mb-3">
                  {soundOn ? <Volume2 className="w-4 h-4 text-[#951E3A]" /> : <VolumeX className="w-4 h-4 text-gray-400" />}
                  <h3 className="font-display font-bold text-gray-800 text-sm uppercase tracking-wide">Sound Effects</h3>
                </div>
                <button onClick={() => { const v = !soundOn; setSoundOn(v); setSoundEnabled(v); }}
                  className={`w-full flex items-center justify-between px-4 py-2.5 rounded-lg border-2 transition-colors ${soundOn ? "border-[#951E3A]/40 bg-[#951E3A]/5" : "border-gray-200"}`}>
                  <span className="text-sm font-semibold text-gray-700">{soundOn ? "On" : "Off"}</span>
                  <span className={`relative w-10 h-6 rounded-full transition-colors ${soundOn ? "bg-[#951E3A]" : "bg-gray-300"}`}>
                    <span className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow transition-all ${soundOn ? "left-[18px]" : "left-0.5"}`} />
                  </span>
                </button>
              </div>

              {/* Data saver */}
              <div>
                <div className="flex items-center gap-2 mb-2">
                  <Wifi className={`w-4 h-4 ${connection.constrained ? "text-[#951E3A]" : "text-gray-400"}`} />
                  <h3 className="font-display font-bold text-gray-800 text-sm uppercase tracking-wide">Data Saver</h3>
                </div>
                <p className="text-xs text-gray-400 mb-3">
                  Auto reacts to Save-Data, offline mode, 2G and unusually slow links. Lite mode stops speculative downloads, heavy font previews and optional effects.
                </p>
                <div className="grid grid-cols-3 gap-1.5 rounded-xl border border-gray-200 bg-gray-50 p-1.5">
                  {["auto", "on", "off"].map((mode) => (
                    <button
                      key={mode}
                      type="button"
                      onClick={() => {
                        setDataSaver(mode);
                        setConnection(setDataSaverMode(mode));
                      }}
                      className={`min-h-9 rounded-lg text-[10px] font-bold uppercase tracking-wide transition-colors ${dataSaver === mode ? "bg-[#951E3A] text-white" : "bg-white text-gray-500 hover:text-gray-800"}`}
                      aria-pressed={dataSaver === mode}
                    >
                      {mode}
                    </button>
                  ))}
                </div>
                <p className="mt-2 text-[10px] text-gray-400">
                  Current path: <span className="font-bold text-gray-600">{connection.constrained ? "Lite" : "Full"}</span>
                  {connection.offline ? " · Offline" : connection.effectiveType !== "unknown" ? ` · ${connection.effectiveType.toUpperCase()}` : ""}
                  {connection.saveData ? " · Save-Data requested" : ""}
                </p>
              </div>

              {/* Motion */}
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <Accessibility className="w-4 h-4 text-[#951E3A]" />
                  <h3 className="font-display font-bold text-gray-800 text-sm uppercase tracking-wide">Animations</h3>
                </div>
                <p className="text-xs text-gray-400 mb-3">Stops all motion across the app. The custom cursor stays.</p>
                <button
                  onClick={() => { const value = !animationsOff; setAnimationsOff(value); setAnimationsDisabled(value); }}
                  className={`w-full flex items-center justify-between px-4 py-2.5 rounded-lg border-2 transition-colors ${animationsOff ? "border-[#951E3A]/40 bg-[#951E3A]/5" : "border-gray-200"}`}
                  aria-pressed={animationsOff}
                >
                  <span className="text-sm font-semibold text-gray-700">{animationsOff ? "Disabled" : "Enabled"}</span>
                  <span className={`relative w-10 h-6 rounded-full transition-colors ${animationsOff ? "bg-[#951E3A]" : "bg-gray-300"}`}>
                    <span className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow transition-all ${animationsOff ? "left-[18px]" : "left-0.5"}`} />
                  </span>
                </button>
              </div>

              {/* Custom cursor */}
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <MousePointer2 className={`w-4 h-4 ${customCursorOn ? "text-[#951E3A]" : "text-gray-400"}`} />
                  <h3 className="font-display font-bold text-gray-800 text-sm uppercase tracking-wide">Custom Cursor</h3>
                </div>
                <p className="text-xs text-gray-400 mb-3">Use the animated liquid cursor on mouse and trackpad devices. Turning it off restores the normal system cursor.</p>
                <button
                  onClick={() => {
                    const value = !customCursorOn;
                    setCustomCursorOn(value);
                    setCustomCursorEnabled(value);
                  }}
                  className={`w-full flex items-center justify-between px-4 py-2.5 rounded-lg border-2 transition-colors ${customCursorOn ? "border-[#951E3A]/40 bg-[#951E3A]/5" : "border-gray-200"}`}
                  aria-pressed={customCursorOn}
                >
                  <span className="text-sm font-semibold text-gray-700">{customCursorOn ? "Enabled" : "Disabled"}</span>
                  <span className={`relative w-10 h-6 rounded-full transition-colors ${customCursorOn ? "bg-[#951E3A]" : "bg-gray-300"}`}>
                    <span className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow transition-all ${customCursorOn ? "left-[18px]" : "left-0.5"}`} />
                  </span>
                </button>
              </div>

              {/* Account */}
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <User className="w-4 h-4 text-[#951E3A]" />
                  <h3 className="font-display font-bold text-gray-800 text-sm uppercase tracking-wide">Account</h3>
                </div>
                <div className="space-y-2">
                  <button onClick={() => base44.auth.logout()}
                    className="w-full flex items-center gap-2 text-left text-sm font-bold text-white bg-[#951E3A] px-3 py-2.5 rounded-lg hover:bg-[#7a1830] transition-colors">
                    <LogOut className="w-4 h-4" /> Sign Out
                  </button>
                </div>
              </div>

              <p className="text-center text-xs text-gray-300 pt-2">Settings are stored on this device.</p>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>, document.body
  );
}